G(30,"norma_culta",3,"Em 'O servidor aspira a um cargo melhor', 'aspirar', no sentido de almejar, é transitivo indireto.","Em 'O servidor aspira um cargo melhor', 'aspirar', no sentido de almejar, é transitivo direto e atende à norma-padrão.","Aspirar (almejar) pede 'a'.","omite a preposição")
G(30,"norma_culta",3,"Em 'Prefiro café a chá', a regência do verbo 'preferir' atende à norma-padrão.","Em 'Prefiro mais café do que chá', a regência do verbo 'preferir' atende à norma-padrão.","Preferir X a Y.","usa 'mais… do que'")
G(30,"norma_culta",2,"O verbo 'desobedecer' é transitivo indireto, como em 'Desobedeceu ao regulamento'.","O verbo 'desobedecer' é transitivo direto, como em 'Desobedeceu o regulamento', segundo a norma-padrão.","Obedecer/desobedecer: 'a'.","trata como transitivo direto")
