Cz(32,"norma_culta",2,"Não ocorre crase diante de verbo, como em 'Começou a votar'.","Ocorre crase diante de verbo, como em 'Começou à votar'.","Verbo não tem artigo.","crase diante de verbo")
Cz(32,"norma_culta",2,"Em regra, não ocorre crase antes de palavra masculina, como em 'Andou a cavalo'.","Em regra, ocorre crase antes de palavra masculina, como em 'Andou à cavalo'.","Masculino sem artigo feminino.","crase diante de masculino")
Cz(32,"norma_culta",2,"Não ocorre crase diante de pronome pessoal, como em 'Entregou o documento a ela'.","Ocorre crase diante de pronome pessoal, como em 'Entregou o documento à ela'.","Pronome pessoal não leva artigo.","crase diante de pronome pessoal")
Cz(32,"norma_culta",3,"Não ocorre crase antes de palavra feminina no plural quando só há preposição: 'Referiu-se a reuniões'.","Ocorre crase antes de palavra feminina no plural quando só há preposição: 'Referiu-se à reuniões'.","Sem artigo, sem crase.","crase sem artigo")
Cz(32,"excecao_omitida",4,"Em 'Voltou a Brasília', não há crase; haverá em 'Voltou à Brasília dos anos 60', por haver especificação.","Em 'Voltou a Brasília', há crase, pois o nome de cidade exige artigo feminino nesse contexto.","Cidade sem artigo, sem crase; com adjunto, há.","aplica crase a toda cidade")
Cz(32,"norma_culta",2,"Em 'Refiro-me àquela decisão', o emprego da crase é adequado.","Em 'Refiro-me àquela decisão', o emprego da crase é indevido.","a + aquela = àquela.","nega a crase em 'àquela'")
Cz(33,"norma_culta",2,"Em 'A reunião começa às nove horas', a crase é obrigatória.","Em 'A reunião começa às nove horas', a crase é facultativa.","Horas determinadas: crase obrigatória.","chama de facultativa")
Cz(33,"norma_culta",3,"A crase é obrigatória em locuções adverbiais femininas, como 'à noite', 'às pressas' e 'à vista'.","A crase é indevida em locuções adverbiais femininas, como 'à noite', 'às pressas' e 'à vista'.","Locução feminina: crase.","nega a crase")
Cz(33,"norma_culta",3,"Em 'A empresa a que me refiro', não há crase.","Em 'A empresa à que me refiro', a crase é exigida.","'Que' não admite crase.","crase antes de 'que'")
Cz(33,"excecao_omitida",3,"Antes de pronome possessivo feminino, a crase é facultativa: 'Obedeceu à/a sua chefe'.","Antes de pronome possessivo feminino, a crase é obrigatória: 'Obedeceu à sua chefe'.","Possessivo: facultativa.","chama de obrigatória")
Cz(33,"excecao_omitida",3,"Antes de nome próprio feminino de pessoa, a crase é facultativa: 'Entreguei o ofício à/a Maria'.","Antes de nome próprio feminino de pessoa, a crase é obrigatória: 'Entreguei o ofício à Maria'.","Nome de pessoa: facultativa.","chama de obrigatória")
