Pn(34,"norma_culta",3,"A frase 'Ele trouxe o texto para eu ler' atende à norma-padrão, pois 'eu' é sujeito de 'ler'.","A frase 'Ele trouxe o texto para mim ler' atende à norma-padrão.","Sujeito de infinitivo: 'eu'.","oblíquo como sujeito")
Pn(34,"norma_culta",2,"A frase 'Isto é para mim' atende à norma-padrão, pois 'mim' é regido pela preposição.","A frase 'Isto é para eu' atende à norma-padrão.","Sem verbo, 'para mim'.","reto sem verbo")
Pn(34,"confusao_instituto",2,"Em 'Informei-lhe o prazo', o pronome 'lhe' funciona como objeto indireto.","Em 'Informei-lhe o prazo', o pronome 'lhe' funciona como objeto direto.","Lhe = indireto.","confunde direto e indireto")
Pn(34,"confusao_instituto",2,"Em 'Encontrei-os no plenário', o pronome 'os' funciona como objeto direto.","Em 'Encontrei-os no plenário', o pronome 'os' funciona como objeto indireto.","O/os = direto.","confunde direto e indireto")
Pn(34,"norma_culta",3,"Pronomes de tratamento levam o verbo e os possessivos na terceira pessoa: 'Vossa Excelência trouxe seus documentos'.","Pronomes de tratamento levam os possessivos na segunda pessoa: 'Vossa Excelência trouxe vossos documentos'.","Tratamento: 3ª pessoa.","usa 2ª pessoa")
Pn(34,"norma_culta",3,"'Vossa Excelência' é usada para falar com o interlocutor, e 'Sua Excelência', para falar dele.","'Sua Excelência' é usada para falar com o interlocutor, e 'Vossa Excelência', para falar dele.","Vossa = com; Sua = sobre.","inverte Vossa e Sua")
Pn(35,"norma_culta",3,"A próclise é obrigatória em 'Não se esqueça do prazo', por haver palavra negativa antes do verbo.","A ênclise é obrigatória em 'Não esqueça-se do prazo', por haver palavra negativa antes do verbo.","Negação atrai o pronome.","impõe ênclise após negação")
Pn(35,"norma_culta",2,"Na norma-padrão, o período não deve começar com pronome oblíquo átono: 'Disseram-me', e não 'Me disseram'.","Na norma-padrão, 'Me disseram' é a forma exigida para iniciar o período.","Não se inicia com átono.","exige próclise inicial")
Pn(35,"norma_culta",3,"Em 'O projeto que se discute', a próclise é motivada pelo pronome relativo 'que'.","Em 'O projeto que se discute', a norma-padrão impõe a ênclise: 'que discute-se'.","Relativo atrai o pronome.","impõe ênclise após relativo")
Pn(35,"norma_culta",3,"A forma 'Dar-lhe-ei o parecer' atende à norma-padrão.","A forma 'Darei-lhe o parecer' atende à norma-padrão.","Futuro: mesóclise ou próclise.","ênclise em futuro")
Pn(35,"norma_culta",3,"Em 'Em se tratando de prazo', a próclise é adequada, por haver gerúndio precedido de 'em'.","Em 'Em tratando-se de prazo', a forma atende à norma-padrão.","Em + gerúndio: próclise.","ênclise com 'em' + gerúndio")
Pn(35,"norma_culta",4,"Em locução verbal com particípio, o pronome átono não se coloca depois do particípio: 'Tinha-me avisado'.","Em locução verbal com particípio, a forma 'Tinha avisado-me' atende à norma-padrão.","Pronome nunca após particípio.","ênclise ao particípio")
Pn(35,"norma_culta",2,"Em 'Ninguém o viu', a próclise é motivada pelo pronome indefinido 'ninguém'.","Em 'Ninguém o viu', a ênclise seria motivada pelo pronome indefinido 'ninguém'.","Indefinido atrai.","inverte o efeito do atrativo")
