Lx(38,"confusao_instituto",3,"'Ratificar' significa confirmar, e 'retificar', corrigir.","'Ratificar' significa corrigir, e 'retificar', confirmar.","Ratificar = confirmar.","inverte os parônimos")
Lx(38,"confusao_instituto",3,"'Infringir' significa transgredir, como em 'infringir a lei'.","'Infringir' significa aplicar uma pena, como em 'infringir a pena'.","Infringir = violar; infligir = aplicar.","troca infringir por infligir")
Lx(38,"confusao_instituto",3,"'Eminente' significa notável, e 'iminente', prestes a ocorrer.","'Eminente' significa prestes a ocorrer, e 'iminente', notável.","Eminente = notável.","inverte os parônimos")
Lx(38,"confusao_instituto",3,"'Deferir' é conceder, e 'diferir', adiar ou distinguir-se.","'Deferir' é adiar, e 'diferir', conceder.","Deferir = conceder.","inverte os parônimos")
Lx(38,"confusao_instituto",3,"'Mandado' é ordem judicial, e 'mandato', período de exercício de função.","'Mandado' é período de exercício de função, e 'mandato', ordem judicial.","Mandado = ordem.","inverte os parônimos")
Lx(38,"confusao_instituto",4,"'Descriminar' é retirar o caráter de crime, e 'discriminar', distinguir ou segregar.","'Descriminar' é distinguir ou segregar, e 'discriminar', retirar o caráter de crime.","Descriminar = legalizar.","inverte os parônimos")
Lx(38,"confusao_instituto",3,"'Emigrar' é sair do país de origem, e 'imigrar', entrar em outro país para viver.","'Emigrar' é entrar em outro país para viver, e 'imigrar', sair do país de origem.","Emigrar = sair.","inverte os parônimos")
Lx(39,"reescrita",2,"Em 'A sessão foi suspensa', o adjetivo 'suspensa' pode ser substituído por 'interrompida' sem mudança essencial de sentido.","Em 'A sessão foi suspensa', o adjetivo 'suspensa' pode ser substituído por 'encerrada' sem mudança essencial de sentido.","Suspensa ≠ encerrada.","troca por termo definitivo")
Lx(39,"conceito_correto",3,"A palavra 'vago' é polissêmica: em 'cargo vago' significa desocupado; em 'ideia vaga', impreciso.","A palavra 'vago' mantém o mesmo sentido em 'cargo vago' e em 'ideia vaga'.","Polissemia: contexto define.","ignora a polissemia")
