# 40 tipologia (LP14)
def Tp(*a): S("LP14",*a)
Tp(40,"confusao_instituto",2,"Predomina a sequência narrativa no texto que relata ações em sucessão temporal, com verbos no pretérito.","Predomina a sequência dissertativa no texto que relata ações em sucessão temporal, com verbos no pretérito.","Ações no tempo = narração.","confunde narração e dissertação")
Tp(40,"confusao_instituto",2,"Textos injuntivos orientam o leitor a agir, com verbos no imperativo, como manuais e receitas.","Textos descritivos orientam o leitor a agir, com verbos no imperativo, como manuais e receitas.","Orientar a agir = injunção.","confunde injunção e descrição")
Tp(40,"confusao_instituto",2,"A sequência dissertativo-argumentativa defende uma tese com argumentos.","A sequência narrativa defende uma tese com argumentos.","Tese + argumentos = dissertação.","confunde narração e dissertação")
Tp(40,"confusao_instituto",2,"Em 'A sala é ampla, clara e ventilada', predomina a sequência descritiva.","Em 'A sala é ampla, clara e ventilada', predomina a sequência narrativa.","Qualidades = descrição.","confunde descrição e narração")
Tp(40,"confusao_instituto",2,"Ofício e memorando são gêneros da redação oficial.","Crônica e soneto são gêneros da redação oficial.","Redação oficial: ofício, memorando, etc.","inclui gêneros literários")
Tp(40,"confusao_instituto",3,"A notícia busca informar sobre fato recente, com linguagem predominantemente referencial.","A notícia busca informar sobre fato recente, com linguagem predominantemente expressiva, marcada pela subjetividade do autor.","Notícia: referencial.","atribui função expressiva")
Tp(40,"confusao_instituto",3,"Uma exposição apresenta e explica um tema, sem necessariamente defender tese.","A exposição tem como traço definidor a defesa de uma tese.","Expor ≠ argumentar.","confunde exposição e argumentação")
