Or(41,"norma_culta",3,"As palavras 'heroico' e 'jiboia' não levam acento, por serem paroxítonas com ditongo aberto 'oi'.","As palavras 'heroico' e 'jiboia' levam acento: 'heróico' e 'jibóia'.","Paroxítona com 'oi': sem acento.","mantém o acento extinto")
Or(41,"norma_culta",2,"A forma verbal 'pôr' leva acento circunflexo para diferenciar-se da preposição 'por'.","A preposição 'por' leva acento circunflexo para diferenciar-se da forma verbal 'pôr'.","Pôr (verbo) tem acento.","inverte o acento")
Or(41,"norma_culta",2,"O acento diferencia 'tem' (singular) de 'têm' (plural).","O acento diferencia 'tem' (plural) de 'têm' (singular).","Têm = plural.","inverte singular e plural")
Or(41,"norma_culta",4,"Em 'anti-inflamatório', usa-se hífen porque o prefixo termina na mesma vogal que inicia o segundo elemento.","A grafia 'antiinflamatório' atende ao Acordo Ortográfico.","Mesma vogal: hífen.","omite o hífen")
Or(41,"norma_culta",3,"Prefixo terminado em vogal seguido de palavra iniciada por vogal diferente dispensa hífen: 'autoescola'.","A grafia 'auto-escola' atende ao Acordo Ortográfico.","Vogais diferentes: sem hífen.","usa hífen indevido")
